from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p121","body":"کسی نئے راستے پر\nپھر اسی ضابطے پر\nنئی منزل کی تلاش میں\nانجانے قافلوں میں\nپھر ملیں گے ہم\n\nخوابوں کے شہر میں\nدل کے کسی نگر میں\nجذبوں کی سرحد پہ\nلامحدود فاصلوں میں\nپھر ملیں گے ہم\n\nگم سم تنہائی میں\nبےاثر  مسیحائی میں\nوحشت زدہ رونقوں میں\nویران محفلوں میں\nپھر ملیں گے ہم\n\nزنگینیوں میں چوڑ\nرنجشوں سے بھرپور\nگرتے،  سنورتے\nبھیگتے ساونوں میں\nپھر ملیں گے ہم\n\nکسی میخانے میں\nکبھی انجانے میں\nکسی شاعری میں\nکئی گانوں میں\nپھر ملیں گے ہم\n\nسرگوشیوں میں\nمدہوشیوں میں\nبےبقا بہاروں میں\nسدا جاڑوں میں\nپھر ملیں گے ہم\n\nاسی زمانے میں\nکسی فسانے میں\nبدلتی رتوں میں\nنئی فرصتوں میں\nپھر ملیں گے ہم\n\nاسی بنچ پہ بیٹھے\nیہی نظم کہتے\nان کہے سوالوں میں\nتمہارے خیالوں میں\nپھر ملیں گے ہم........"},{"slug":"tum-p122","body":"اک آنسو پلکوں تک آتا ناگوار ہوا\nیہ بھی کون سا کوئی پہلی بار ہوا\n\nتو نے بچھڑتے کوئی مشورہ نہیں کیا\nمت کہہ کہ تجھ کو بھی پیار ہوا\n\nاک مکان تھا آسائشوں سے پُر\nتیرے آنے سے جو دیار ہوا\n\nدل کا کیا، مستقبل کی بات کرو\nدل یہ قدیم یادوں کا کباڑ ہوا\n\nتیرے ہجر کے حشر میں\nتیرا خوب انتظار ہوا\n\nتیری باتوں میں سچائی تھی دوست\nمگر تیرا لہجہ جگر کے پار ہوا\n\nبات ساری فطرت کی ہی تھی\nکوئی گل سے جڑا بھی اور خار ہوا\n\nایک شخص سے محبت کر کے دیکھ لیا\nاحمد ؔ ایک شخص مزید درکار ہوا"},{"slug":"tum-p123","body":"حال یہ کہ خود حال پہ ہنس رہا ہوں میں\nماضی کے کسی دلدل میں ڈھنس رہا ہوں میں\n\nہے ہر طرف وحشت بھری اداسی\nاور بیچ کہیں پس رہا ہوں میں\n\nجب سے بادلوں نے برسنا چھوڑا ہے\nتب سے مسلسل برس رہا ہوں میں\n\nکئی عرصہ ہجرت کے بعد بھی\nخود ہی اپنا قفس رہا ہوں میں\n\nوہ سبھی آئینے ٹوٹ گئے ہیں احمد ؔ\nجن آئینوں کا کبھی عکس رہا ہوں میں"},{"slug":"tum-p124","body":"دل یہ جانم کھلونا ہی تھا\nجو ہوا یہ تو ہونا ہی تھا\n\nخوابوں پہ لگے ہیں مجھ پہ فتوے\nتھک کے آخر کو تو سونا ہی تھا\n\nپاس بیٹھیں پر اس قدر بھی نہ کہ رو دیں\nآپ کے جانے پہ بھی ہم نے رونا ہی تھا\n\nوہ ہمیشہ ایسے مجھ سے دور بھاگے ہیں\nاحمد ؔ جیسے وبا سے پہلے بھی کرونا ہی تھا"},{"slug":"tum-p125","body":"دو ستاروں کی طرح\nہم دو تھے یکساں\nتم تھے کہ روشن تھے\nہم تھے فقط بھجے ہوئے\nتم تھے زینت سماں کی\nہم بس مثل خزاں تھے\nتم فقط تم تھے\nہم تھے جیسے تم سے\nتمہاری اپنی شناخت تھی\nہماری تم سے کائنات تھی\nمگر ان ستاروں کی طرح\nتمہاری بھی اپنی منزل تھی\nہماری بھی جدا تھی منزل\nنہ ہم آسکے تمہارے محور میں\nنہ تم نے آنے کی ہمت کی\nآخر ہم نے دور سے بس یہ کہا\nکچھ بھی ممکن نہیں ہمارا"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
